import json,statistics
from pathlib import Path
p=Path('art/previews/gfx5b4c-a4-final');m=json.loads((p/'gpu-60'/'metrics.json').read_text());f=json.loads((p/'gpu-60'/'foot-transition-measurements.json').read_text());matches=json.loads((p/'gpu-60'/'video-position-estimates.json').read_text());
lines=['# C03 A4 — kiểm chứng chân, camera và FPS','','## Kết luận','', 'Chưa đủ cơ sở đề xuất C03 làm chuẩn kỹ thuật. Đã đo được dấu hiệu trượt chân theo proxy từ layer chân ở cả tám hướng. Các proxy chưa xác nhận chắc danh tính chân và trạng thái tiếp đất, nên không coi số này là sai số tiếp đất chính xác. Một thử nghiệm sửa cục bộ làm mất hoặc méo phần bàn chân; đã loại thử nghiệm và không thay asset A4 trong game. Chưa khẳng định camera không rung trong mọi frame/zoom. Người dùng quyết định mỹ thuật cuối.','','## FPS render và video — cùng NPC, cùng WorldScene, ×1','', 'Renderer thử headless GPU: NVIDIA Quadro 600 Direct3D11, WebGL; viewport 1280×720. FPS render tính từ POST_RENDER và performance.now; FPS video tính từ số frame giải mã và timestamp PTS. Các lần đo nối tiếp, không phải phép đo song song ngẫu nhiên.','', '| Cảnh | Zoom | FPS render | Frame time median / p95 | Video (frame / thời gian / FPS PTS) |','|---|---:|---:|---:|---|']
for n,label in [('fixed_no_recorder','Camera cố định, không ghi'),('fixed_recorded','Camera cố định, ghi video'),('follow_recorded','Camera follow, ghi video'),('follow_zoom_in','Camera follow, zoom tăng')]:
 v=m[n];vd=v.get('video');video=f"{vd['frames']} / {vd['ptsSec']:.2f}s / {vd['fps']:.2f}" if vd else 'không ghi';lines.append(f"| {label} | {v['zoom']:.3f} | {v['renderFPS']:.2f} | {v['medianMs']:.1f} / {v['p95Ms']:.1f} ms | {video} |")
lines+=['','FPS render khoảng 57,5–60 trong điều kiện GPU này. Video đặt captureStream(60), thực tế giải mã khoảng 48–50 FPS; không đồng nhất FPS video với FPS render. Lần no-recorder chạy trước khi nóng máy, nên không dùng sự chênh lệch để khẳng định tác động hiệu năng của recorder.','', 'Đối chứng SwiftShader cũ: `measurement.json` ở thư mục cha, render khoảng 10–13 FPS; chính trình kiểm thử cũ ép `--use-angle=swiftshader`. Các file video headless software mới bị ngắn/thiếu frame; không dùng chúng để đánh giá chuyển động. Kết quả GPU không đảm bảo FPS trên mọi máy/cảnh.','','## Tám hướng và proxy chân','', 'Nguồn A4: canvas 32×40, origin (0.5,1) tương ứng pivot (16,40), scale (1,1); tốc độ walk NPC thường 42 world px/s ở ×1; animation walk sáu frame/hướng, 120 ms/frame. Các frame `2→3` và `5→6` được chọn theo cờ nâng chân trong script nguồn.','', 'Cách tính: điểm dưới cùng của layer `legs` trong nửa trái/phải màn hình; world foot proxy = world pivot + tọa độ cục bộ − (16,40). Lấy delta giữa mẫu render đầu của hai frame liên tiếp. Đây là proxy từ layer có thể bị che; nửa trái/phải màn hình không luôn là cùng một chân giải phẫu, nhất là hướng ngang. Chưa có nhãn tác giả xác nhận tiếp đất, do đó các trị số chỉ là dấu hiệu, không phải trượt chân đã xác định hoàn toàn.','', '| Hướng | Số chuyển frame mẫu | Trung vị khoảng dịch proxy (world px) | Trung vị thời gian | Đánh giá |','|---|---:|---:|---:|---|']
for d in ['N','NE','E','SE','S','SW','W','NW']:
 a=[x for x in f if x['direction']==d];lines.append(f"| {d} | {len(a)} | {statistics.median(x['distanceWorldPx'] for x in a):.2f} | {statistics.median(x['dtMs'] for x in a):.1f} ms | Có dấu hiệu; cần xác nhận chân chống |")
lines+=['','Ở zoom 1,15, nếu camera cố định, world px nhân 1,15 cho độ dịch màn hình lý thuyết; camera follow có dịch chuyển riêng và không được dùng hệ số này một mình. `foot-transition-measurements.json` có từng delta world và screen dự kiến; `foot-poses-candidates.png` chấm cam/xanh chỉ hai nửa màn hình, không phải chân trái/phải đã xác nhận.','', 'Đã thử hai bản sửa layer chân 2px và 3–4px từ A4: ảnh `candidate-comparison.png` / `candidate-small-comparison.png` cho thấy một số giày bị che hoặc méo. Với frame 34, proxy dưới cùng bên phải từ 25 pixel trong A4 xuống 0 pixel ở bản dịch lớn. Cả hai bản chỉ là ứng viên bị loại; không tích hợp runtime và không sửa 18 frame đặc biệt.','','## Camera, zoom và pixel','', 'Đã đo camera cố định và follow với cùng vòng lộ trình; zoom mặc định 1,15 và zoom tăng theo bước có sẵn ×1,12 thành 1,288. Các video GPU 60 và chuỗi `renderer-sequence-fixed.png` / `renderer-sequence-follow.png` là ảnh WorldScene thật. Chuỗi snapshot được yêu cầu trực tiếp ở thời điểm render có kiểm soát, không dùng tốc độ thu ảnh để suy ra FPS game.','', 'Camera và renderer báo `roundPixels=true`, antialias=false; texture scaleMode=1, tương ứng nearest-neighbor trong Phaser. Tuy nhiên sprite có `vertexRoundMode=safeAuto`: ở zoom 1,15, ma trận scale khoảng 1,15 nên `onlyTranslated=false` và `willRoundVertices=false`. Vì vậy không suy ra đỉnh sprite đã được làm tròn chỉ từ `roundPixels`. Tọa độ physics không bị làm tròn.','', 'Đối chiếu ước lượng template lên video nén và sample gần nhất trong 20ms, chỉ giữ correlation≥0,96:']
for n,label in [('fixed_recorded','cố định'),('follow_recorded','follow')]:
 v=matches[n];lines.append(f"- {label}: {v['matched']}/{v['decoded']} frame qua bộ lọc; p95 trị tuyệt đối sai khác top-left ước lượng so với ma trận dự đoán: x={v['residualX']['p95Abs']:.2f}px, y={v['residualY']['p95Abs']:.2f}px.")
lines+=['','Đây là ước lượng trên tập con được chọn, ảnh nén và đồng bộ gần đúng, không phải phép đọc tọa độ đỉnh GPU; không dùng để tuyên bố mọi frame không rung. Không đổi cấu hình camera vì chưa chứng minh một lỗi camera cần sửa.','', '## Bằng chứng và tương thích','', '- `gpu-60/fixed_recorded.webm` và `gpu-60/follow_recorded.webm`: video WorldScene thật, tám hướng, ×1. `gpu-60/fixed-world-video-frames.png` và `gpu-60/follow-world-video-frames.png` là khung hình lấy mẫu theo thời gian video; snapshot renderer ở thư mục cha là lượt chụp có điều khiển riêng.','- `measurement.json`, `gpu-60/measurement.json`, `gpu-60/metrics.json`, `gpu-60/video-position-estimates.json`: dữ liệu render/video và ước lượng. 18 frame đặc biệt A4, ID NPC, AI, tốc độ, collision, save và fallback giữ nguyên.','- Kết quả kiểm chứng depth, reload và AI ở `../gfx5b4c-a4-verify/REPORT-VI.md`. Các video software thu riêng có thể không đầy đủ; không dùng để kết luận.','- TypeScript/Vite build, `test:systems`, direction/occlusion/prototype tests đạt. Debug đo lường chỉ bật với `devtest=1`, `gfx5b4c4=1`, `gfx5b4c4verify=1`, `gfx5b4c4final=1`.','','## Kiểm kê frame tạm VERIFY','', '| Thư mục | Số PNG | Dung lượng bytes |','|---|---:|---:|']
base=Path('art/previews/gfx5b4c-a4-verify')
for n in ['marker-frames-v2','marker-video-frames','motion-frames','tree-transition-frames']:
 files=list((base/n).glob('frame-*.png'));lines.append(f'| {n} | {len(files)} | {sum(x.stat().st_size for x in files)} |')
lines+=['','Tổng 270 PNG khoảng 281 MiB là frame trích trung gian; các video, ảnh tổng hợp, metadata, báo cáo và Aseprite là bằng chứng/nguồn cần giữ. Đợt này không thử lại lệnh xóa và không tìm cách vượt policy.']
(p/'REPORT-VI.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print('Final evidence report written')
